import{_ as a,a as t,c as r,ac as o}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"雅思词汇真经","description":"从主题词汇、搭配、词族和主动输出建立词汇学习方法，不混用不同版次的单元目录。","frontmatter":{"title":"雅思词汇真经","description":"从主题词汇、搭配、词族和主动输出建立词汇学习方法，不混用不同版次的单元目录。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 语言学习与出国考试 · 雅思备考专项","summary":"从主题词汇、搭配、词族和主动输出建立词汇学习方法，不混用不同版次的单元目录。","status":"active","related":[{"title":"雅思阅读真经总纲","link":"/life/personal/books/languages/ielts-reading","kind":"书籍导读","scope":"general","audience":"general"},{"title":"雅思口语真经总纲","link":"/life/personal/books/languages/ielts-speaking","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"雅思阅读真经总纲","link":"/life/personal/books/languages/ielts-reading"},"next":{"text":"雅思口语真经总纲","link":"/life/personal/books/languages/ielts-speaking"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"雅思阅读真经总纲","link":"/life/personal/books/languages/ielts-reading"},"next":{"text":"雅思口语真经总纲","link":"/life/personal/books/languages/ielts-speaking"}},"headers":[],"relativePath":"life/personal/books/languages/ielts-vocabulary.md","filePath":"life/personal/books/languages/ielts-vocabulary.md"}'),l={name:"life/personal/books/languages/ielts-vocabulary.md"};function n(s,e,i,d,h,p){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="雅思词汇真经" tabindex="-1">雅思词汇真经 <a class="header-anchor" href="#雅思词汇真经" aria-label="Permalink to &quot;雅思词汇真经&quot;">​</a></h1><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p><strong>分类：语言学习与出国考试 → 雅思备考专项。</strong> 词汇书可以把教育、环境、科技等常见语境中的词放在一起，帮助阅读理解与口头表达形成联系。真正的掌握包括读音、核心含义、搭配、使用场合，以及在句子中辨认和调用词语。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p><strong>《雅思词汇真经》：作者为刘洪波。</strong> <a href="https://opac.hnu.edu.cn/opac/book/2000366392" target="_blank" rel="noopener noreferrer">湖南大学图书馆</a>与<a href="https://item.xhsd.com/items/110000100192766" target="_blank" rel="noopener noreferrer">新华书店</a>共同列出2018年外语教学与研究出版社版、ISBN 9787521304558。<a href="https://www.ieltscb.com/PageInfos/vocabulary" target="_blank" rel="noopener noreferrer">作者教学平台</a>也提供同名词汇学习内容。其相关经验是雅思教学和教材编写；词汇选择属于教学取舍，并非官方规定的封闭词表，早期同名版本不能混用目录。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合已有基础词汇、希望按语境整理雅思词汇的考生。认识单词却写不出自然句子的人，可优先练搭配和主动回忆；基础较弱者需同时补读音、词性与常见义。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>已核到2018年外研社版的作者与ISBN，用户具体版次未指定。<strong>具体版次待确认；以下为本站主题导读，不是原书目录。</strong> 不把某版章节与词条数量视为所有版本共有，也不承诺覆盖考试全部词汇。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题导读</th><th>阅读重点</th><th>学习产物</th></tr></thead><tbody><tr><td>人与日常生活</td><td>将人物、关系、活动和感受放入具体场景，区分近义词语气。</td><td>一组关于自身日常生活的自然表达。</td></tr><tr><td>教育与工作</td><td>积累学习、培训、就业和协作相关的常见搭配。</td><td>围绕一个观点写出原因、例子和限制。</td></tr><tr><td>社会与城市</td><td>理解公共服务、人口、交通等话题中的词义关系。</td><td>用词汇网络连接问题、原因、措施与影响。</td></tr><tr><td>科技与环境</td><td>关注过程、变化、因果和数量表达，不只背名词。</td><td>用简单句解释一项技术或一个环境问题。</td></tr><tr><td>词族与搭配</td><td>观察同根词的词性变化，识别介词和动词搭配。</td><td>给每个重点词配一个可复用的词组。</td></tr><tr><td>复习与输出</td><td>将“看见认识”逐步转为“听见理解”和“需要时能用”。</td><td>间隔回忆、听写、短文复述，分别检查薄弱环节。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p><strong>本站阅读评析：</strong> 单词量只是学习的一个侧面。把一个词的中文意思记得很牢，却不知道它通常与什么动词搭配，写作时仍容易产生不自然的句子。每次少记一些词、多保留一个真实用例，往往更有助于长期使用。</p><p>阅读和听力中的生词也应回流到词汇笔记：记录它出现的句子、上下文和误解原因。词汇书提供整理框架，实际语境帮助校准用法。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><p><strong>本站原创阅读提炼，不是原书引用：</strong> 记住一个词的译义只是入口，能在合适句子里使用才是下一步。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p><strong>本站阅读评析，非书单提供者亲历：</strong> 每个主题选少量重点词，记录常见搭配和能理解的例句，再合书复述短文。将阅读错题的同义改写补入词群笔记，分别检查看见能认、听见能懂和需要能说。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>主题编排方便建立联系，也可能让近义词混淆，需要回到句子辨认语气与搭配。熟悉书中列表不能直接换算考试成绩。<strong>推荐语：</strong> 用它建立词汇框架，让真实阅读和听力继续修正用法。</p><h2 id="来源或核对入口" tabindex="-1">来源或核对入口 <a class="header-anchor" href="#来源或核对入口" aria-label="Permalink to &quot;来源或核对入口&quot;">​</a></h2><ul><li><a href="https://ielts.org/" target="_blank" rel="noopener noreferrer">IELTS 官方网站</a>：核对考试内容及官方备考材料。</li><li><a href="https://search.worldcat.org/search?q=%E9%9B%85%E6%80%9D%E8%AF%8D%E6%B1%87%E7%9C%9F%E7%BB%8F" target="_blank" rel="noopener noreferrer">WorldCat 题名检索</a>：核对具体版本；本页主题不是据此抄录的原书目录。</li></ul><p><a href="./../overview">返回书单总览</a></p>',23)])])}const u=a(l,[["render",n]]);export{g as __pageData,u as default};
